import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import { BRAND } from "@/lib/brand";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  compoundReveal,
  inOutEnvelope,
} from "../motion";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 15;

const ITEMS = [
  { label: "No more API keys", descriptor: "One unified gateway, zero key management" },
  { label: "No more account creation", descriptor: "Skip the sign-up loops for every tool" },
  { label: "No more credit cards", descriptor: "Drop the form-filling and verification dance" },
  { label: "No more billing complexity", descriptor: "Single invoice, one predictable line item" },
];

const Background: React.FC = () => (
  <AbsoluteFill style={{ background: COLORS.bg }}>
    {/* Soft radial wash for depth — stays within dark-gray + orange grammar */}
    <div
      style={{
        position: "absolute",
        inset: 0,
        background: `radial-gradient(120% 80% at 18% 22%, rgba(248,102,6,0.06), transparent 55%), radial-gradient(90% 60% at 85% 90%, rgba(248,102,6,0.04), transparent 60%)`,
      }}
    />
    {/* Bottom decorative dotted band — Apify "rising stars" motif at low opacity */}
    <svg
      viewBox="0 0 2160 2160"
      style={{ position: "absolute", inset: 0, width: "100%", height: "100%", opacity: 0.35 }}
    >
      <defs>
        <pattern id="dots" width="28" height="28" patternUnits="userSpaceOnUse">
          <circle cx="2" cy="2" r="1.6" fill={COLORS.orange} opacity={0.5} />
        </pattern>
        <linearGradient id="dotMask" x1="0" y1="1" x2="0" y2="0">
          <stop offset="0%" stopColor="white" stopOpacity={0.7} />
          <stop offset="100%" stopColor="white" stopOpacity={0} />
        </linearGradient>
        <mask id="bandMask">
          <rect x="0" y="1700" width="2160" height="460" fill="url(#dotMask)" />
        </mask>
      </defs>
      <rect x="0" y="0" width="2160" height="2160" fill="url(#dots)" mask="url(#bandMask)" />
    </svg>
    {/* Bottom-right orange wedge — restrained, ~6% of frame */}
    <svg
      viewBox="0 0 2160 2160"
      style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }}
    >
      <polygon
        points="2160,1700 2160,2160 1620,2160"
        fill={COLORS.orangeDeep}
        opacity={0.14}
      />
    </svg>
  </AbsoluteFill>
);

const CheckIcon: React.FC<{ size: number; progress: number }> = ({ size, progress }) => {
  const dashOffset = interpolate(progress, [0, 1], [40, 0]);
  const ringScale = interpolate(progress, [0, 1], [0.4, 1]);
  const ringOpacity = interpolate(progress, [0, 0.4, 1], [0, 1, 1]);
  return (
    <svg width={size} height={size} viewBox="0 0 48 48" style={{ flexShrink: 0 }}>
      <circle
        cx={24}
        cy={24}
        r={22}
        fill="none"
        stroke={COLORS.orange}
        strokeWidth={2.5}
        opacity={ringOpacity * 0.9}
        style={{
          transformOrigin: "24px 24px",
          transform: `scale(${ringScale})`,
        }}
      />
      <circle
        cx={24}
        cy={24}
        r={22}
        fill={COLORS.orangeTint}
        opacity={ringOpacity}
        style={{
          transformOrigin: "24px 24px",
          transform: `scale(${ringScale})`,
        }}
      />
      <path
        d="M14 24.5 L21 31 L34 17"
        stroke={COLORS.orange}
        strokeWidth={4}
        strokeLinecap="round"
        strokeLinejoin="round"
        fill="none"
        strokeDasharray={40}
        strokeDashoffset={dashOffset}
      />
    </svg>
  );
};

const ChecklistRow: React.FC<{
  item: (typeof ITEMS)[number];
  index: number;
  baseDelay: number;
}> = ({ item, index, baseDelay }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const rowIn = staggeredSpring(
    frame,
    vfps,
    index,
    baseDelay,
    TIMING.staggerItem,
    "GENTLE",
  );
  const checkIn = staggeredSpring(
    frame,
    vfps,
    index,
    baseDelay + 3,
    TIMING.staggerItem,
    "LIQUID",
  );

  const driftY = ambientDrift(frame, 1.2, 110 + index * 13, `row-${index}`);

  const tx = interpolate(rowIn, [0, 1], [-32, 0]);

  return (
    <div
      style={{
        display: "flex",
        alignItems: "flex-start",
        gap: 36,
        opacity: rowIn,
        transform: `translate(${tx}px, ${driftY}px)`,
      }}
    >
      <div style={{ marginTop: 6 }}>
        <CheckIcon size={72} progress={checkIn} />
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 600,
            fontSize: 80,
            color: COLORS.text,
            letterSpacing: "-0.022em",
            lineHeight: 1.08,
          }}
        >
          {item.label}
        </div>
        <div
          style={{
            fontFamily: "Inter, sans-serif",
            fontWeight: 400,
            fontSize: 34,
            color: COLORS.textMuted,
            letterSpacing: "-0.003em",
            lineHeight: 1.3,
          }}
        >
          {item.descriptor}
        </div>
      </div>
    </div>
  );
};

const HeadlineScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, durationInFrames: dur } = useVideoConfig();

  const envelope = inOutEnvelope(frame, vfps, dur);

  const eyebrowIn = springIn(frame, vfps, TIMING.entrance, "GENTLE");
  const titleIn = springIn(frame, vfps, TIMING.entrance + 6, "SNAPPY");
  const highlightIn = springIn(frame, vfps, TIMING.entrance + 18, "LIQUID");
  const cardIn = springIn(frame, vfps, TIMING.entrance + 14, "LIQUID");

  const titleDriftY = ambientDrift(frame, 2.2, 130, "title");
  const eyebrowDriftX = ambientDrift(frame, 1.5, 95, "eyebrow");

  const titleTx = interpolate(titleIn, [0, 1], [28, 0]);
  const titleBl = interpolate(titleIn, [0, 1], [10, 0]);
  const cardTy = interpolate(cardIn, [0, 1], [40, 0]);
  const cardSc = interpolate(cardIn, [0, 1], [0.96, 1]);

  const highlightClip = interpolate(highlightIn, [0, 1], [100, 0]);

  return (
    <AbsoluteFill style={{ fontFamily: "Inter, sans-serif", opacity: envelope }}>
      <Background />

      {/* Off-center anchored layout — left-aligned column, padding asymmetric */}
      <div
        style={{
          position: "absolute",
          left: 170,
          right: 170,
          top: 220,
          bottom: 200,
          display: "flex",
          flexDirection: "column",
          gap: 80,
        }}
      >
        {/* Eyebrow label */}
        <div
          style={{
            fontFamily: "Inter, sans-serif",
            fontWeight: 600,
            fontSize: 32,
            color: COLORS.textSubtle,
            letterSpacing: "0.18em",
            textTransform: "uppercase",
            opacity: eyebrowIn,
            transform: `translateX(${interpolate(eyebrowIn, [0, 1], [-12, 0]) + eyebrowDriftX}px)`,
            display: "flex",
            alignItems: "center",
            gap: 20,
          }}
        >
          <div
            style={{
              width: 56,
              height: 2,
              background: COLORS.orange,
              borderRadius: 1,
            }}
          />
          Apify and X402 
        </div>

        {/* Headline */}
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 700,
            fontSize: 156,
            color: COLORS.text,
            letterSpacing: "-0.032em",
            lineHeight: 1.02,
            opacity: titleIn,
            transform: `translateY(${titleTx + titleDriftY}px)`,
            filter: `blur(${titleBl}px)`,
            maxWidth: 1500,
          }}
        >
          One connection.{"\u00A0"}
          <span
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              display: "inline-block",
              position: "relative",
            }}
          >
            <span
              style={{
                position: "absolute",
                inset: "6% -12px",
                background: COLORS.orangeTint,
                borderBottom: `4px solid ${COLORS.orange}`,
                borderRadius: 10,
                clipPath: `inset(0 ${highlightClip}% 0 0)`,
                zIndex: 0,
              }}
            />
            <span style={{ position: "relative", zIndex: 1, fontFamily: "'GT Walsheim', Inter, sans-serif" }}>
              zero overhead.
            </span>
          </span>
        </div>

        {/* Checklist card */}
        <div
          style={{
            background: "rgba(29,30,31,0.85)",
            border: `1px solid ${COLORS.border}`,
            borderRadius: 22,
            padding: "64px 72px",
            display: "flex",
            flexDirection: "column",
            gap: 52,
            opacity: cardIn,
            transform: `translateY(${cardTy}px) scale(${cardSc})`,
            backdropFilter: "blur(8px)",
            boxShadow: "0 24px 80px rgba(0,0,0,0.45)",
          }}
        >
          {ITEMS.map((item, i) => (
            <ChecklistRow
              key={i}
              item={item}
              index={i}
              baseDelay={TIMING.entrance + 26}
            />
          ))}
        </div>
      </div>
    </AbsoluteFill>
  );
};

const sceneDuration = 200;

export const durationInFrames = sceneDuration;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={sceneDuration}>
        <HeadlineScene />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
